SELECT a.id, a.title, a.summary, a.author_id AS authorId, a.category_id AS categoryId, a.is_top AS isTop, a.status, a.update_time AS updateTime, c.name AS categoryName, u.nickname AS authorName, COALESCE(like_stats.like_count, 0) AS likeCount, COALESCE(comment_stats.comment_count, 0) AS commentCount FROM article a LEFT JOIN category c ON a.category_id = c.id LEFT JOIN users u ON a.author_id = u.id LEFT JOIN ( SELECT article_id, COUNT(*) AS like_count FROM article_like GROUP BY article_id ) like_stats ON a.id = like_stats.article_id LEFT JOIN ( SELECT article_id, COUNT(*) AS comment_count FROM comment GROUP BY article_id ) comment_stats ON a.id = comment_stats.article_id WHERE a.id IN
#{id}
AND a.del_flag = false

SELECT author_id AS authorId, COUNT(*) AS total FROM article WHERE del_flag = 0 AND author_id IN
#{id}
GROUP BY author_id
